argv:
$ErrorActionPreference='Stop'
$tmp=Join-Path $env:TEMP 'pc-iphone-page3-filter-inspect.mjs'
try{[System.IO.File]::WriteAllText($tmp,@'
setTimeout(()=>{console.log('{"error":"timeout"}');process.exit(0)},6500);
try{const t=(await(await fetch('http://127.0.0.1:17447/json/list')).json()).find(x=>x.id==='D229F01C94F7F6DF012309BB4CE211CD');
const w=new WebSocket(t.webSocketDebuggerUrl);
w.addEventListener('open',()=>w.send(JSON.stringify({id:1,method:'Runtime.evaluate',params:{expression:'window.scrollTo(0,1200); ({scrollY:window.scrollY,query:location.search})',returnByValue:true}})),{once:true});
w.addEventListener('message',e=>{const z=JSON.parse(e.data);if(z.id===1){console.log(JSON.stringify(z.result?.result?.value||{error:'no_value'}));process.exit(0)}})
}catch(e){console.log(JSON.stringify({error:String(e).slice(0,120)}));process.exit(0)}
'@,[System.Text.UTF8Encoding]::new($false));& node.exe $tmp}finally{Remove-Item $tmp -Force -ErrorAction SilentlyContinue}
